import{_ as e,o as i,c as r,a4 as n}from"./chunks/framework.BAxM5-cj.js";const h=JSON.parse('{"title":"Sprint 6 — Workspace, Client & Subscription","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_06_Workspace_Client_Subscription.md","filePath":"plan/sprints/Sprint_06_Workspace_Client_Subscription.md"}'),a={name:"plan/sprints/Sprint_06_Workspace_Client_Subscription.md"};function s(d,t,o,c,l,p){return i(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="sprint-6-—-workspace-client-subscription" tabindex="-1">Sprint 6 — Workspace, Client &amp; Subscription <a class="header-anchor" href="#sprint-6-—-workspace-client-subscription" aria-label="Permalink to &quot;Sprint 6 — Workspace, Client &amp; Subscription&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 11–12 (Jul 29–Aug 11, 2026) <strong>Jira:</strong> DA Sprint 6 <strong>Phase:</strong> Phase 3 — Backend Core <strong>Goal:</strong> Implement workspace CRUD, client/agency management, and subscription/billing APIs in business-service.</p><p>&gt; <strong>AI Parallel:</strong> AI Iteration 1 runs concurrently this sprint (final week).</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E15</td><td>Workspace Management</td><td>Trung</td></tr><tr><td>E16</td><td>Client &amp; Agency Management</td><td>Trung</td></tr><tr><td>E17</td><td>Subscription &amp; Billing</td><td>Trung, Ân</td></tr></tbody></table><p><strong>Deliverables by end of Sprint 6:</strong></p><ul><li>Full workspace CRUD: create, get, invite member, remove member, settings</li><li>Client management: create, assign account manager, set service package, list</li><li>Subscription plans CRUD (Admin)</li><li>Subscribe to plan + payment flow + invoice history</li></ul><hr><h2 id="epic-e15-—-workspace-management" tabindex="-1">EPIC E15 — Workspace Management <a class="header-anchor" href="#epic-e15-—-workspace-management" aria-label="Permalink to &quot;EPIC E15 — Workspace Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E15-01</td><td>Implement POST /api/v1/workspaces (create new workspace, AGENCY_OWNER role)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E15-02</td><td>Implement GET /api/v1/workspaces/mine (get current user&#39;s workspace)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E15-03</td><td>Implement POST /api/v1/workspaces/{id}/members (invite member via email)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E15-04</td><td>Implement DELETE /api/v1/workspaces/{id}/members/{userId} (remove member)</td><td>Trung (Leader)</td><td>🟡 High</td></tr><tr><td>DA-E15-05</td><td>Implement workspace settings (timezone, default platforms, report frequency)</td><td>Trung (Leader)</td><td>🟡 High</td></tr></tbody></table><p><strong>Workspace invite flow (DA-E15-03):</strong></p><ol><li>AGENCY_OWNER POSTs <code>{email, role}</code> → system checks if user exists</li><li>If user exists: add to <code>workspace_members</code>, notify user</li><li>If not exists: send invite email with registration link pre-filled with workspaceId</li><li>Role options for invite: ACCOUNT_MANAGER, CONTENT_CREATOR</li></ol><p><strong>Notes:</strong></p><ul><li>One user can only belong to one workspace (enforced at invite time).</li><li>AGENCY_OWNER cannot remove themselves — must transfer ownership first (out of scope for MVP).</li></ul><hr><h2 id="epic-e16-—-client-agency-management" tabindex="-1">EPIC E16 — Client &amp; Agency Management <a class="header-anchor" href="#epic-e16-—-client-agency-management" aria-label="Permalink to &quot;EPIC E16 — Client &amp; Agency Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E16-01</td><td>Implement POST /api/v1/clients (AGENCY_OWNER creates new brand client)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E16-02</td><td>Implement PUT /api/v1/clients/{id}/assign (AGENCY_OWNER assigns Account Manager)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E16-03</td><td>Implement PUT /api/v1/clients/{id}/service-package (set post limit/month and platforms)</td><td>Trung (Leader)</td><td>🟡 High</td></tr><tr><td>DA-E16-04</td><td>Implement GET /api/v1/clients (AGENCY_OWNER and ACCOUNT_MANAGER view client list)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>Client document fields:</strong><code>clientId</code>, <code>workspaceId</code>, <code>name</code>, <code>industry</code>, <code>brandColor</code>, <code>logoUrl</code>, <code>assignedAccountManagerId</code>, <code>servicePackage: {postsPerMonth, platforms[], aiCreditsPerMonth}</code>, <code>createdAt</code></p><p><strong>Notes:</strong></p><ul><li>ACCOUNT_MANAGER can only see clients assigned to them (<code>assignedAccountManagerId == currentUserId</code>).</li><li>Service package on client is separate from workspace subscription — client-level limit ≤ workspace subscription limit.</li></ul><hr><h2 id="epic-e17-—-subscription-billing" tabindex="-1">EPIC E17 — Subscription &amp; Billing <a class="header-anchor" href="#epic-e17-—-subscription-billing" aria-label="Permalink to &quot;EPIC E17 — Subscription &amp; Billing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E17-01</td><td>Implement Admin CRUD for subscription plans (Free/Basic/Pro/Enterprise)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E17-02</td><td>Implement POST /api/v1/subscriptions/subscribe (AGENCY_OWNER subscribes to a plan)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E17-03</td><td>Implement payment flow (integrate payment gateway, create invoice)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E17-04</td><td>Implement GET /api/v1/subscriptions/invoices (billing history)</td><td>Ân (AI)</td><td>🟡 High</td></tr></tbody></table><p><strong>Subscription plans (seed data from Sprint 4):</strong></p><table tabindex="0"><thead><tr><th>Plan</th><th>Price</th><th>Clients</th><th>Posts/mo</th><th>AI Credits/mo</th></tr></thead><tbody><tr><td>Free</td><td>$0</td><td>1</td><td>10</td><td>20</td></tr><tr><td>Basic</td><td>$29</td><td>5</td><td>50</td><td>100</td></tr><tr><td>Pro</td><td>$79</td><td>20</td><td>200</td><td>500</td></tr><tr><td>Enterprise</td><td>$199</td><td>Unlimited</td><td>Unlimited</td><td>2000</td></tr></tbody></table><p><strong>Payment gateway (DA-E17-03):</strong> Use Stripe (test mode for capstone). Flow: <code>POST /subscribe</code> → create Stripe PaymentIntent → client confirms → webhook callback → create <code>invoices</code> record + activate subscription.</p><p><strong>Notes:</strong></p><ul><li>DA-E17-03 Stripe integration: store only Stripe customer ID and subscription ID in PostgreSQL, never raw card data.</li><li>Invoice PDF generation is out of scope for MVP — store invoice data as JSON, PDF generation in Sprint 16 if time permits.</li></ul><hr><h2 id="sprint-6-checklist" tabindex="-1">Sprint 6 Checklist <a class="header-anchor" href="#sprint-6-checklist" aria-label="Permalink to &quot;Sprint 6 Checklist&quot;">​</a></h2><ul><li>[ ] POST /api/v1/workspaces creates workspace, creator becomes AGENCY_OWNER</li><li>[ ] Invite member: email sent, user added to workspace_members on accept</li><li>[ ] Remove member: user loses workspace access immediately</li><li>[ ] Workspace settings: timezone + default platforms + report frequency saved</li><li>[ ] POST /api/v1/clients creates client under workspace</li><li>[ ] Assign account manager: client.assignedAccountManagerId updated</li><li>[ ] Service package set: postsPerMonth + platforms enforced</li><li>[ ] Admin can create/edit/delete subscription plans</li><li>[ ] AGENCY_OWNER can subscribe to a plan via Stripe test mode</li><li>[ ] Invoice record created after successful payment</li><li>[ ] GET /api/v1/subscriptions/invoices returns paginated invoice history</li></ul>',32)])])}const g=e(a,[["render",s]]);export{h as __pageData,g as default};
